const synthPresets={
  lofi:{name:'Lofi Keys',description:'Dusty, softened keys with chorus and room tone.',wave:'triangle',cutoff:3200,attack:.02,release:1.1,sat:25,chorus:35,delay:18,reverb:32,noise:12,pump:0},
  house:{name:'Deep House Pluck',description:'Short, bright pluck with tempo delay and sidechain-style pumping.',wave:'sawtooth',cutoff:2200,attack:.005,release:.32,sat:18,chorus:10,delay:24,reverb:12,noise:0,pump:58},
  pad:{name:'Warm Pad',description:'Slow analog pad with wide chorus and a long ambient tail.',wave:'sawtooth',cutoff:1800,attack:.75,release:2.8,sat:14,chorus:48,delay:10,reverb:58,noise:4,pump:12},
  sub:{name:'Sub Bass',description:'Rounded low-end voice with subtle saturation and no ambience.',wave:'sine',cutoff:650,attack:.01,release:.45,sat:34,chorus:0,delay:0,reverb:0,noise:0,pump:28}
};
const synthKeyMap={a:60,w:61,s:62,e:63,d:64,f:65,t:66,g:67,y:68,h:69,u:70,j:71,k:72};
const synthNotes=[60,61,62,63,64,65,66,67,68,69,70,71,72];
const synthNames=['C','C♯','D','D♯','E','F','F♯','G','G♯','A','A♯','B','C'];
const synthActive=new Map();let synthBus=null,synthBusContext=null;
function synthSettings(){const p=synthPresets[$('#synthPreset').value];return {...p,cutoff:+$('#synthCutoff').value,attack:+$('#synthAttack').value,release:+$('#synthRelease').value,sat:+$('#synthSat').value,chorus:+$('#synthChorus').value,delay:+$('#synthDelay').value,reverb:+$('#synthReverb').value,noise:+$('#synthNoise').value,pump:+$('#synthPump').value}}
function synthCurve(amount){const n=2048,out=new Float32Array(n),k=amount*3;for(let i=0;i<n;i++){const x=i*2/n-1;out[i]=(1+k)*x/(1+k*Math.abs(x))}return out}
function createSynthBus(ac,dest,s){const input=ac.createGain(),filter=ac.createBiquadFilter(),sat=ac.createWaveShaper(),sum=ac.createGain(),dry=ac.createGain(),chorusDelay=ac.createDelay(),chorusWet=ac.createGain(),lfo=ac.createOscillator(),lfoDepth=ac.createGain(),delay=ac.createDelay(),delayWet=ac.createGain(),feedback=ac.createGain(),conv=ac.createConvolver(),revWet=ac.createGain(),master=ac.createGain();filter.type='lowpass';filter.frequency.value=s.cutoff;filter.Q.value=1.5;sat.curve=synthCurve(s.sat/100);sat.oversample='2x';dry.gain.value=1;chorusDelay.delayTime.value=.02;chorusWet.gain.value=s.chorus/100*.6;lfo.frequency.value=.7;lfoDepth.gain.value=.006;lfo.connect(lfoDepth).connect(chorusDelay.delayTime);lfo.start();delay.delayTime.value=60/Math.max(40,+$('#bpm').value)*.75;delayWet.gain.value=s.delay/100*.55;feedback.gain.value=.28;conv.buffer=impulse(ac,2.2);revWet.gain.value=s.reverb/100*.65;master.gain.value=1;input.connect(filter).connect(sat);sat.connect(dry).connect(sum);sat.connect(chorusDelay).connect(chorusWet).connect(sum);sum.connect(master).connect(dest);sum.connect(delay);delay.connect(feedback).connect(delay);delay.connect(delayWet).connect(dest);sum.connect(conv).connect(revWet).connect(dest);if(s.pump>0){const pump=ac.createOscillator(),depth=ac.createGain();pump.frequency.value=Math.max(40,+$('#bpm').value)/60;depth.gain.value=s.pump/100*.28;master.gain.value=1-s.pump/100*.18;pump.connect(depth).connect(master.gain);pump.start()}if(s.noise>0){const n=ac.createBufferSource(),g=ac.createGain(),f=ac.createBiquadFilter();n.buffer=noiseBuffer(ac,2);n.loop=true;f.type='highpass';f.frequency.value=3500;g.gain.value=s.noise/100*.025;n.connect(f).connect(g).connect(dest);n.start()}return input}
function ensureSynthBus(){initAudio();const s=synthSettings();if(!synthBus||synthBusContext!==ctx){synthBus=createSynthBus(ctx,ctx.destination,s);synthBusContext=ctx}return synthBus}
function midiFreq(n){return 440*Math.pow(2,(n-69)/12)}
function synthNoteOn(note){if(synthActive.has(note))return;const s=synthSettings(),input=ensureSynthBus(),gain=ctx.createGain(),o1=ctx.createOscillator(),o2=ctx.createOscillator(),now=ctx.currentTime;o1.type=s.wave;o2.type=s.wave;o1.frequency.value=midiFreq(note);o2.frequency.value=midiFreq(note);o1.detune.value=-6;o2.detune.value=6;gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(s.wave==='sine'?.36:.22,now+Math.max(.005,s.attack));o1.connect(gain);o2.connect(gain);gain.connect(input);o1.start();o2.start();synthActive.set(note,{o1,o2,gain});document.querySelector(`[data-note="${note}"]`)?.classList.add('active')}
function synthNoteOff(note){const v=synthActive.get(note);if(!v)return;const s=synthSettings(),now=ctx.currentTime;v.gain.gain.cancelScheduledValues(now);v.gain.gain.setTargetAtTime(.0001,now,Math.max(.02,s.release/4));v.o1.stop(now+s.release+0.1);v.o2.stop(now+s.release+0.1);synthActive.delete(note);document.querySelector(`[data-note="${note}"]`)?.classList.remove('active')}
function synthPanic(){[...synthActive.keys()].forEach(synthNoteOff)}
function applySynthPreset(){const p=synthPresets[$('#synthPreset').value];for(const [id,key] of [['synthCutoff','cutoff'],['synthAttack','attack'],['synthRelease','release'],['synthSat','sat'],['synthChorus','chorus'],['synthDelay','delay'],['synthReverb','reverb'],['synthNoise','noise'],['synthPump','pump']])$('#'+id).value=p[key];$('#synthDescription').textContent=p.description;synthBus=null;syncSynthLabels()}
function syncSynthLabels(){$('#synthCutoffOut').value=(+$('#synthCutoff').value/1000).toFixed(1)+' kHz';$('#synthAttackOut').value=(+$('#synthAttack').value).toFixed(2)+' s';$('#synthReleaseOut').value=(+$('#synthRelease').value).toFixed(2)+' s';for(const id of ['Sat','Chorus','Delay','Reverb','Noise','Pump'])$('#synth'+id+'Out').value=$('#synth'+id).value+'%'}
function buildSynthKeys(){const el=$('#synthKeys');el.innerHTML='';synthNotes.forEach((note,i)=>{const b=document.createElement('button');b.type='button';b.className='synth-key '+([1,3,6,8,10].includes(note%12)?'black':'');b.dataset.note=note;b.textContent=synthNames[i];b.onpointerdown=e=>{e.preventDefault();synthNoteOn(note)};b.onpointerup=()=>synthNoteOff(note);b.onpointerleave=()=>synthNoteOff(note);el.appendChild(b)})}
function scheduledSynthNote(ac,bus,n,start,duration,s){const gain=ac.createGain(),o1=ac.createOscillator(),o2=ac.createOscillator();o1.type=s.wave;o2.type=s.wave;o1.frequency.value=midiFreq(n);o2.frequency.value=midiFreq(n);o1.detune.value=-6;o2.detune.value=6;gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(s.wave==='sine'?.36:.2,start+Math.max(.005,s.attack));gain.gain.setValueAtTime(s.wave==='sine'?.36:.2,start+duration);gain.gain.exponentialRampToValueAtTime(.0001,start+duration+s.release);o1.connect(gain);o2.connect(gain);gain.connect(bus);o1.start(start);o2.start(start);o1.stop(start+duration+s.release+.05);o2.stop(start+duration+s.release+.05)}
async function addSynthLoop(){const s=synthSettings(),bpm=Math.max(40,+$('#bpm').value),bar=60/bpm*4,total=bar*4,off=new OfflineAudioContext(2,Math.ceil((total+s.release+2.5)*44100),44100),bus=createSynthBus(off,off.destination,s),progressions={lofi:[[60,63,67,70],[56,60,63,67],[63,67,70,74],[58,62,65,69]],house:[[60,63,67],[56,60,63],[63,67,70],[58,62,65]],pad:[[48,55,60,63],[44,51,56,60],[51,58,63,67],[46,53,58,62]],sub:[[36],[32],[39],[34]]},chords=progressions[$('#synthPreset').value];chords.forEach((ch,i)=>ch.forEach(n=>scheduledSynthNote(off,bus,n,i*bar,bar*.72,s)));const rendered=await off.startRendering(),raw=encodeWav(rendered);remember();const t=makeTrack(s.name);clips.push({id:uid(),trackId:t.id,name:`${s.name} Loop`,start:pausedAt,offset:0,duration:total,buffer:rendered,peaks:getPeaks(rendered),raw});selectedClip=clips.at(-1).id;markDirty();render();$('#synthDialog').close();toast(`${s.name} loop added`)}
function wireSynth(){$('#synthBtn').onclick=()=>{$('#synthDialog').showModal();buildSynthKeys();applySynthPreset()};$('#closeSynthBtn').onclick=()=>{synthPanic();$('#synthDialog').close()};$('#panicSynthBtn').onclick=synthPanic;$('#addSynthLoopBtn').onclick=addSynthLoop;$('#synthPreset').onchange=()=>{synthPanic();applySynthPreset()};for(const id of ['synthCutoff','synthAttack','synthRelease','synthSat','synthChorus','synthDelay','synthReverb','synthNoise','synthPump'])$('#'+id).oninput=()=>{syncSynthLabels();synthBus=null};document.addEventListener('keydown',e=>{if(e.repeat||!$('#synthDialog').open||e.target.matches('input,select'))return;const n=synthKeyMap[e.key.toLowerCase()];if(n!==undefined)synthNoteOn(n)});document.addEventListener('keyup',e=>{const n=synthKeyMap[e.key.toLowerCase()];if(n!==undefined)synthNoteOff(n)});syncSynthLabels()}
wireSynth();
